import {yamahaTestShow} from './yamaha-shows.js';
export function fxTestShow(model){const s=yamahaTestShow(model),dm=!!consoleModel(s).dm,dm3=isDM3(s);s.mixes.push(makeMix('BUS',3,{name:'FX DLY',mode:'ST',type:'FX',mute:false,fader:0}));s.fx=[{id:'hall',slot:1,model:dm3?'RevHDHall':dm?'Rev. HD Hall':'REV-X HALL',usage:'send',returnN:dm&&!dm3?5:1,sendLeft:1,sendRight:2,mix:100,bypass:false,main:true,returnLevel:-6,returnMute:false,sends:{},matrixSends:{1:{on:true,level:-11,tap:'POST'}}}];if(dm3){s.fx.push({...s.fx[0],id:'delay',slot:2,model:'PingPongDelay',returnN:2,main:false,returnMute:true,returnLevel:-12,matrixSends:{}});s.channels[0].fxSends={1:{on:true,level:-18,tap:'POST'},2:{on:true,level:-21,tap:'PRE'}};}else{s.fx.push({...s.fx[0],id:'delay',slot:dm?3:2,model:dm?'Mono Delay':'MONO DELAY',returnN:dm?7:2,sendLeft:3,sendRight:4,matrixSends:{},returnMute:true});s.fx.push({id:'bus-insert',slot:dm?4:3,model:dm?'M. Band Comp':'COMP276S',usage:'insert',target:'BUS',targetN:1,insertSlot:1,position:'postins',mix:100,bypass:false},{id:'ch-insert',slot:dm?5:4,model:dm?'Classic Flanger':'EQUALIZER601',usage:'insert',target:'CH',targetN:1,insertSlot:2,position:'postins',mix:65,bypass:true});}return s;}
export function premiumTestShow(model){const s=fxTestShow(model),dm=!!consoleModel(s).dm;if(isDM3(s))return s;s.pyDsp=consoleModel(s).dm==='dm5';s.mixes.push(makeMix('MTX',1,{name:'MATRIX',mode:'M',fader:0,mute:false}),makeMix('BUS',5,{name:'PR SEND',mode:'M',fader:0,mute:false}));const basic={rack:'premium',usage:'insert',mix:100,bypass:false,position:'postins',target:'BUS',targetN:1,insertSlot:2};s.fx.push({...basic,id:'pr-u76',slot:dm?1:5,model:'U76 St'},{...basic,id:'pr-dual',slot:dm?17:3,model:'Portico5033 Dual',target:'MTX',targetN:1,insertSlot:1,rightTarget:'BUS.5'},{...basic,id:'pr-send',slot:dm?4:1,model:dm?'REV-X':'Portico5043 St',usage:'send',returnN:dm?9:3,sendLeft:5,sendRight:dm?0:5,returnLevel:-9,returnMute:true,main:true,sends:{},matrixSends:{1:{on:true,level:-13,tap:'POST'}}});return s;}
